INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('zheltyy-nalet-unitaz', 'zheltyy-nalet-unitaz', 'Жёлтый налёт и мочевой камень в унитазе', 'scale', 'bathroom', 'фаянс / керамика / нержавеющая чаша', 'set', 'b2c', '[{"order":1,"instruction":"Наденьте перчатки, проветрите санузел и перекройте подачу воды в бачок (грушу или вентиль)."},{"order":2,"instruction":"Нанесите кислотный очиститель с цитрусовой кислотой или сульфаминовую кислоту (pH 2–3) под ободок и на жёлтые разводы. Выдержите 15–20 минут, не допуская высыхания.","tip":"Старый налёт снимается в 2–3 приёма: лучше повторить, чем тереть сухой жёсткой щёткой."},{"order":3,"instruction":"Потрите мягким спонжем или старой зубной щёткой под ободком, смойте большим количеством воды и включите подачу воды."}]', '["Не смешивайте кислоту с хлорсодержащими средствами: выделяется ядовитый газ хлора.","Не используйте абразивные порошки и металлические губки: остаются микроцарапины, в которых налёт садится снова.","Не оставляйте кислоту на акриловой ванне и силиконовых уплотнителях дольше 5 минут."]', 'Если налёт минеральный и въелся в поры фаянса старше года, либо в санузле коммерческого объекта. Мастер применяет профессиональный дескалер с плотной выдержкой и механической обработкой под ободком.', '10 – 30 BYN (кислотный очиститель, перчатки)', '40 – 60 минут', '["желтый налет в унитазе","камень в унитазе","мочевой камень","чистка унитаза","налет под ободком"]', 'deep-cleaning', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('chay-na-obivke', 'chay-na-obivke', 'Пятно чая или кофе на диване и кресле', 'stain', 'upholstery', 'велюр / рогожка / шенилл / микрофибра', 'fresh', 'b2c', '[{"order":1,"instruction":"Промокните лужицу сухими салфетками от краёв к центру, не втирая жидкость в ворс."},{"order":2,"instruction":"Нанесите на микрофибру раствор лимонной кислоты (1 ч.л. на стакан воды) или специализированный пятновыводитель для текстиля. Танины чая обесцвечиваются слабой кислотой.","tip":"Сначала проверьте средство на скрытом участке: на окрашенном велюре краситель может сойти."},{"order":3,"instruction":"Прижимайте салфетку к пятну 1–2 минуты, затем промойте участок чуть влажной чистой салфеткой и просушите под прессом сухого полотенца."}]', '["Не используйте горячую воду и не сушите феном: танин чая «заваривается» в волокне и пятно становится коричневым навсегда.","Не трите щёткой: ворс распушится и пятно расползётся по ткани."]', 'Если пятно старше суток, обивка из натуральной кожи или замши, либо после домашней попытки осталось рыжее кольцо. Мастер выводит танин экстрактором с кислотным ополаскиванием.', '5 – 20 BYN (лимонная кислота, микрофибра, пятновыводитель)', '30 – 50 минут', '["чай на диване","пятно от чая","чай на обивке","рыжее пятно на диване","крепкий чай пятно"]', 'upholstery', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('sok-na-kovre', 'sok-na-kovre', 'Пятно фруктового или детского сока на ковре', 'stain', 'carpet', 'ковёр / ковролин / палас', 'fresh', 'b2c', '[{"order":1,"instruction":"Соберите лужицу сухими полотенцами, прижимая их ладонью — не размазывайте сок по ворсу."},{"order":2,"instruction":"Приготовьте раствор: 1 ст.л. белого уксуса на стакан прохладной воды (для цветных соков — только мыльная пена pH 7). Нанесите на салфетку и промаквайте пятно.","tip":"Виноградный и гранатовый сок содержат танин: без кислоты он останется розовым следом."},{"order":3,"instruction":"Промойте участок чистой салфеткой с водой, просушите под прессом и расчешите ворс щёткой по направлению pile."}]', '["Не используйте горячую воду: сахара сока свариваются в ворсе и пятно становится липким и тёмным.","Не трите мокрый ковёр щёткой: ворс склеится и останется залом."]', 'Если сок впитался в подложку и пятно с обратной стороны, ковёр натуральный (шерсть, шёлк, вискоза), либо пятно уже высохло более суток. Нужна экстракционная промывка с контролем усадки.', '3 – 15 BYN (уксус, мыльная пена, микрофибра)', '40 – 70 минут + сушка', '["сок на ковре","детский сок пятно","виноградный сок ковер","фруктовый сок на паласе","убрать сок с ковра"]', 'upholstery', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('shokolad-na-kovre', 'shokolad-na-kovre', 'Пятно шоколада или конфеты на ковре', 'stain', 'carpet', 'ковёр / ковролин / ковровое покрытие', 'fresh', 'b2c', '[{"order":1,"instruction":"Соскребите застывший шоколад тупой стороной ножа или пластиковой карты, двигаясь по направлению ворса."},{"order":2,"instruction":"Остатки жира выведите мыльной пеной или средством для ковров с энзимами — масло какао расщепляется щелочным составом."},{"order":3,"instruction":"Промокните пятно чистой салфеткой, просушите и при необходимости повторите для остаточного жёлтого следа."}]', '["Не используйте горячую воду и не проглаживайте утюгом: масло какао впитается глубже и оставит несмываемое пятно.","Не трите пятно до удаления твёрдой фазы — крошки вдавятся в ворс."]', 'Если шоколад был с орехами/карамелью и жир ушёл в подложку, либо ковёр из натуральной шерсти или шёлка. Мастер выводит масляный след экстрактором с обезжиривателем.', '5 – 20 BYN (мыльная пена, средство для ковров)', '45 – 75 минут', '["шоколад на ковре","пятно шоколада","шоколад на диване","убрать шоколад с ковра","пятно от конфеты"]', 'upholstery', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('krov-na-kovre', 'krov-na-kovre', 'Пятно крови на ковре или ковролине', 'stain', 'carpet', 'ковёр / ковролин / палас', 'fresh', 'b2c', '[{"order":1,"instruction":"Промокните кровь холодной водой (ниже 15°C) салфетками от краёв к центру — только холод, белок крови при нагреве сворачивается."},{"order":2,"instruction":"Нанесите на ватный диск 3% перекись водорода или соль растворения, прижимайте к пятну 1–2 минуты, сразу промакивая результат.","tip":"Перекись обесцвечивает гемоглобин: на цветном ковре сначала проверьте на скрытом участке."},{"order":3,"instruction":"Промойте холодной водой с мыльной пеной, просушите под прессом и расчешите ворс."}]', '["Категорически запрещена горячая или тёплая вода: белок сворачивается и пятно фиксируется в волокне навсегда.","Не используйте хлорку и горячий фен: на шерсти и шёлке они разрушают волокно и краску."]', 'Если кровь старше 24 часов, ковёр из натуральных волокон, либо пятно большое (порез, носовое кровотечение). Мастер применяет белковый нейтрализатор и экстрактор с контролем температуры.', '2 – 15 BYN (перекись, мыльная пена, салфетки)', '50 – 80 минут + сушка', '["кровь на ковре","пятно крови ковролин","кровь на паласе","как вывести кровь с ковра","кровь на ковровом покрытии"]', 'upholstery', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('plesen-na-stenah', 'plesen-na-stenah', 'Чёрная плесень на стенах и потолке ванной', 'scale', 'bathroom', 'краска / обои / плитка / затирка', 'set', 'b2c', '[{"order":1,"instruction":"Проветрите помещение, наденьте перчатки и респиратор — споры плесени опасны при вдыхании."},{"order":2,"instruction":"Обработайте очаги гелем с активным хлором или профессиональным антисептиком, выдержите по инструкции (15–30 минут), не допуская высыхания.","tip":"На обоях и краске используйте только средства с пометкой «для окрашенных поверхностей»."},{"order":3,"instruction":"Смойте обработанные участки и просушите стену феном или обогревателем — главное убрать источник влаги, иначе плесень вернётся."}]', '["Не смешивайте хлорсодержащие средства с кислотами и аммиаком — выделяются ядовитые газы.","Не красьте и не грунтуйте поражённую стену до полного уничтожения спор — плесень прорастёт сквозь отделку.","При площади очага более 1 м² и заражении систем вентиляции нужна профессиональная обработка."]', 'Если плесень задела обои, мягкую мебель, изоляцию или потолок, либо возвращается после каждой уборки — значит, источник сырости в стене. Нужна сушка, антисептическая обработка и диагностика утепления.', '15 – 45 BYN (хлорный гель, антисептик, респиратор)', '1 – 2 часа + сушка до 3 суток', '["плесень на стене","черная плесень стены","плесень в ванной","плесень на потолке","как убрать плесень со стен"]', 'deep-cleaning', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('zhir-na-kuhonnyh-fasadah', 'zhir-na-kuhonnyh-fasadah', 'Жирные пятна и копоть на кухонных фасадах и технике', 'stain', 'kitchen', 'МДФ / эмаль / пластик / стеклокерамика', 'set', 'both', '[{"order":1,"instruction":"Снимите ручки и наклейки, защитите столешницу и технику рядом — щёлочь оставляет следы на поверхности."},{"order":2,"instruction":"Нанесите щелочной обезжириватель (pH 11–12) на загрязнение на 10–15 минут — жир старше недели требует выдержки, а не трения.","tip":"Для эмалевых и стеклянных фасадов подойдёт и лимонная кислота 10%: она срезает окисленный жир без разводов."},{"order":3,"instruction":"Смойте состав и протрите фасад микрофиброй, затем пройдите всё чистой водой с каплей нейтрального средства."}]', '["Не используйте абразивные губки и порошки: на эмали и плёнке останутся микроповреждения, в которых жир будет садиться снова.","Не наносите щёлочь на натуральное дерево и лакированные поверхности — дерево потемнеет и покоробится.","Не допускайте попадания состава на силиконовые уплотнители и ручки — материал теряет эластичность."]', 'Если фасады покрыты плёнкой или шпоном и жир въелся под кромку, кухня после ремонта/пожара с копотью, либо нужна мойка вытяжки и техники «под ключ». Мастер применяет парогенератор и промышленный обезжириватель без химии.', '10 – 35 BYN (обезжириватель, микрофибра)', '1 – 2 часа на кухню', '["жир на кухонных фасадах","копоть на кухне","жирные пятна на мебели","как отмыть кухню от жира","жир на плите фасад"]', 'deep-cleaning', NULL, 'published', 1794397061530, 1794397061530);
INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `status`, `created_at`, `updated_at`) VALUES ('pota-na-obivke', 'pota-na-obivke', 'Жёлтые пятна пота и запах на обивке дивана и изголовье', 'odor', 'upholstery', 'велюр / рогожка / экокожа / натуральная кожа', 'set', 'b2c', '[{"order":1,"instruction":"Проветрите комнату и пропылесосьте обивку — пыль смешается с потом и закрепит запах."},{"order":2,"instruction":"Нанесите энзимный очиститель для текстиля или раствор нашатырного спирта (1 ч.л. на литр воды) на жёлтые ореолы — пот выводится только окислителем, не отдушками.","tip":"На экокоже и коже используйте только средства для кожи — спирт разрушает покрытие."},{"order":3,"instruction":"Прижимайте салфетку к пятну до исчезновения желтизны, затем обработайте всё место нейтрализатором запаха и просушите."}]', '["Не используйте хлорку и горячую воду: на белковых загрязнениях они сворачивают пятно и оставляют жёлтый след.","Не маскируйте запах освежителями — бактерии пота продолжат разлагаться и запах усилится."]', 'Если пот впитался в поролон изголовья или дивана, пятна старше недели, либо обивка натуральная кожа/замша. Нужна промывка экстрактором с ферментным составом и нейтрализация запаха озоном.', '20 – 45 BYN (энзимный очиститель, нейтрализатор запаха)', '60 – 90 минут + сушка', '["пот на диване","желтые пятна на обивке","запах пота мебель","пятна на изголовье","убрать запах с дивана"]', 'upholstery', NULL, 'published', 1794397061530, 1794397061530);
